	/*
	 * Try slow way with current upcase table
	 */
	{
		struct {
			u8 len;
			u8 unused;
			u16 name[NTFS_NAME_LEN];
		} uni_buf;

		uni = (struct cpu_str *)&uni_buf;

		sbi = dentry->d_sb->s_fs_info;

		err = ntfs_nls_to_utf16(sbi, name->name, name->len, uni,
					NTFS_NAME_LEN, UTF16_HOST_ENDIAN);
		if (err < 0)
			return err;

		if (!err)
			return -EINVAL;

		hash = ntfs_names_hash(uni->name, uni->len, sbi->upcase,
				       init_name_hash(dentry));
		name->hash = end_name_hash(hash);
		return 0;
	}
}

edits.before:
	/*
	 * Try slow way with current upcase table
	 */
	uni = __getname();
	if (!uni)
		return -ENOMEM;

	sbi = dentry->d_sb->s_fs_info;

	err = ntfs_nls_to_utf16(sbi, name->name, name->len, uni, NTFS_NAME_LEN,
				UTF16_HOST_ENDIAN);
	if (err < 0)
		goto out;

	if (!err) {
		err = -EINVAL;
		goto out;
	}

	hash = ntfs_names_hash(uni->name, uni->len, sbi->upcase,
			       init_name_hash(dentry));
	name->hash = end_name_hash(hash);
	err = 0;

out:
	__putname(uni);
	return err;
}

